CREATE SCHEMA ding_control;
REVOKE ALL ON SCHEMA ding_control FROM PUBLIC;
SET LOCAL search_path=ding_control,pg_catalog;

CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY,name TEXT NOT NULL,username TEXT UNIQUE,password TEXT,disabled boolean NOT NULL DEFAULT false,created_at bigint NOT NULL);
CREATE TABLE identities(issuer TEXT NOT NULL,subject TEXT NOT NULL,ding_user TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(issuer,subject));
CREATE TABLE workspaces(id TEXT PRIMARY KEY,name TEXT NOT NULL,created_at bigint NOT NULL,deleting boolean NOT NULL DEFAULT false);
CREATE TABLE memberships(ding_user TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN ('viewer','editor','administrator','owner')),PRIMARY KEY(ding_user,workspace));
CREATE TABLE audit(sequence bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor TEXT NOT NULL,workspace TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,at bigint NOT NULL);
CREATE TABLE service_grants(id TEXT PRIMARY KEY,hash TEXT UNIQUE NOT NULL,name TEXT NOT NULL,workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,created_by TEXT NOT NULL,scopes TEXT NOT NULL,watches TEXT NOT NULL,expires_at bigint NOT NULL);
CREATE TABLE activations(hash TEXT PRIMARY KEY,ding_user TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,expires_at bigint NOT NULL);
CREATE TABLE secrets(workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,name TEXT NOT NULL,ciphertext bytea NOT NULL,PRIMARY KEY(workspace,name));
CREATE TABLE usage(workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,period TEXT NOT NULL,checks bigint NOT NULL DEFAULT 0,deliveries bigint NOT NULL DEFAULT 0,bytes bigint NOT NULL DEFAULT 0,PRIMARY KEY(workspace,period));
CREATE TABLE reservations(id TEXT PRIMARY KEY,workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,period TEXT NOT NULL,created_at bigint NOT NULL);
CREATE INDEX reservations_account ON reservations(workspace);
CREATE TABLE sessions(hash TEXT PRIMARY KEY,ding_user TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,scopes TEXT NOT NULL,workspace TEXT NOT NULL,csrf TEXT NOT NULL,kind TEXT NOT NULL,expires_at bigint NOT NULL);
CREATE INDEX sessions_account ON sessions(workspace);
CREATE TABLE logins(hash TEXT PRIMARY KEY,ciphertext bytea NOT NULL,expires_at bigint NOT NULL);
CREATE TABLE probes(workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,id TEXT NOT NULL,digest TEXT NOT NULL,outcome TEXT NOT NULL,at bigint NOT NULL,PRIMARY KEY(workspace,id));
CREATE TABLE devices(id TEXT PRIMARY KEY,ding_user TEXT REFERENCES users(id) ON DELETE CASCADE,scopes TEXT,challenge TEXT NOT NULL,workspace TEXT REFERENCES workspaces(id) ON DELETE CASCADE,expires_at bigint NOT NULL);
CREATE TABLE mcp_bindings(ding_user TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,client TEXT NOT NULL,credential_hash TEXT NOT NULL UNIQUE,ciphertext bytea NOT NULL,PRIMARY KEY(ding_user,workspace,client));
CREATE TABLE handoff_proofs(workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,id TEXT NOT NULL,body bytea NOT NULL,PRIMARY KEY(workspace,id));


ALTER TABLE service_grants ADD COLUMN lifetimes TEXT NOT NULL DEFAULT '{}';
CREATE TABLE service_keys(id TEXT PRIMARY KEY,service TEXT NOT NULL REFERENCES service_grants(id) ON DELETE CASCADE,hash TEXT UNIQUE NOT NULL,expires_at bigint NOT NULL,created_at bigint NOT NULL,last_used_at bigint NOT NULL DEFAULT 0);
CREATE INDEX service_keys_service ON service_keys(service);
INSERT INTO service_keys(id,service,hash,expires_at,created_at) SELECT id,id,hash,expires_at,0 FROM service_grants;

CREATE TABLE webhook_connections(id TEXT PRIMARY KEY,workspace TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,lifetime TEXT NOT NULL,body bytea NOT NULL,secret bytea NOT NULL,previous bytea,previous_until bigint NOT NULL);
CREATE TABLE writer(singleton integer PRIMARY KEY CHECK(singleton=1));
INSERT INTO writer(singleton) VALUES(1);
